import math

def solve_quadratic(a, b, c):
    discriminant = b*b - 4*a*c
    if discriminant < 0:
        return []

    sqrt_d = math.isqrt(discriminant)
    if sqrt_d * sqrt_d != discriminant:
        return [] # Not an integer solution

    q1 = (-b + sqrt_d) / (2 * a)
    q2 = (-b - sqrt_d) / (2 * a)

    solutions = []
    if q1 == int(q1):
        solutions.append(int(q1))
    if q2 == int(q2):
        solutions.append(int(q2))

    return solutions

def is_prime(n):
    if n < 2:
        return False
    for i in range(2, int(math.sqrt(n)) + 1):
        if n % i == 0:
            return False
    return True

P_values = [2, 3, 5]
results = {}

for P in P_values:
    # Equation: q^2 - q + (1 - P^3) = 0
    a = 1
    b = -1
    c = 1 - P**3

    q_solutions = solve_quadratic(a, b, c)

    primes_q = []
    for q in q_solutions:
        if is_prime(q):
            primes_q.append(q)

    results[P] = {
        "solutions": q_solutions,
        "prime_q": primes_q
    }

print("--- Results ---")
for P, data in results.items():
    print(f"P = {P}:")
    print(f"  Solutions for q: {data['solutions']}")
    print(f"  Prime solutions for q: {data['prime_q']}")

